const cfg=window.VASE_VOW_CONFIG;const pageDialog=document.querySelector('#page-dialog');let lastFocus;
function openDialog(d){lastFocus=document.activeElement;d.showModal();d.querySelector('.close').focus()}
document.querySelectorAll('.page-preview').forEach(b=>b.addEventListener('click',()=>{const im=document.querySelector('#page-image');im.src=b.dataset.page;im.alt=b.dataset.label;document.querySelector('#page-title').textContent=b.dataset.label;openDialog(pageDialog)}));
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.addEventListener('close',()=>lastFocus?.focus())});
document.querySelector('[data-terms]').addEventListener('click',()=>openDialog(document.querySelector('#terms-dialog')));
const purchase=document.querySelector('.purchase');const note=document.querySelector('.checkout-note');purchase.addEventListener('click',()=>{if(cfg.launchReady&&cfg.checkoutUrl){const u=new URL(cfg.checkoutUrl);if(u.protocol==='https:'&&(u.hostname==='gumroad.com'||u.hostname.endsWith('.gumroad.com'))){for(const k of ['utm_source','utm_medium','utm_campaign','utm_content']){const v=new URLSearchParams(location.search).get(k);if(v)u.searchParams.set(k,v.slice(0,100))}location.href=u.href;return}}note.textContent='Checkout is not available yet. You can open the free 3-page sample.';note.setAttribute('tabindex','-1');note.focus()});
const sticky=document.querySelector('.sticky');let heroVisible=true,offerVisible=false;function updateSticky(){sticky.hidden=heroVisible||offerVisible||matchMedia('(min-width:761px)').matches}new IntersectionObserver(es=>{heroVisible=es[0].isIntersecting;updateSticky()},{threshold:0}).observe(document.querySelector('.hero .actions'));new IntersectionObserver(es=>{offerVisible=es[0].isIntersecting;updateSticky()},{threshold:.15}).observe(document.querySelector('#offer'));window.addEventListener('resize',updateSticky);
